const body = $input.first().json.body || $input.first().json;
const payload = body.payload || body;
const from = payload.from || payload.chatId || body.from || '';
const messageText = (payload.body || payload.text || '').trim();
const sessionName = body.session || 'default';
const isFromMe = payload.fromMe || false;
const isGroup = from.includes('@g.us');
if (isFromMe || isGroup) return [{ json: { skip: true } }];
const cleanPhone = from.replace('@c.us', '').replace('@s.whatsapp.net', '');
const msgLower = messageText.toLowerCase().trim();

// DETECÇÃO DE MÍDIA
const type = payload.type || body.type || '';
const hasMedia = payload.hasMedia || ['audio', 'ptt', 'image', 'video', 'sticker', 'document'].includes(type) || (!messageText && type);
const isMedia = !!hasMedia;

const isReactivation = ['#bot', '/bot', '#ativar', '/ativar'].includes(msgLower);
const greetingRegex = /^(oi|ol[aá]|boa tarde|bom dia|boa noite|hey|hello|tudo bem|tudo bom|e a[ií]|oie|oii)[\s!?.]*$/i;
const isGreeting = greetingRegex.test(messageText.trim()) && !isMedia;
const criticalRegex = /(atendente|humano|pessoa|rescis[aã]o|procon|jur[ií]dico|advogado|processo|justi[çc]a|reclama[çc][aã]o|cancel|distrato|falar com algu[eé]m|quero falar)/i;
const isCritical = criticalRegex.test(messageText) && !isMedia;
return [{ json: { skip: false, from, phone: cleanPhone, message: messageText, session: sessionName, isReactivation, isGreeting, isCritical, isMedia, timestamp: new Date().toISOString() } }];

const from = $input.first().json.from;
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
if (staticData.humanHandoff[from]) delete staticData.humanHandoff[from];
return [{ json: { to: from, session: $input.first().json.session, responseText: '✅ Olá! Estou de volta para te ajudar com informações sobre os empreendimentos LongView. Como posso te auxiliar?' } }];

const from = $input.first().json.from;
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
const handoffEntry = staticData.humanHandoff[from];
let isInHumanMode = false;
if (handoffEntry) {
  const elapsed = Date.now() - new Date(handoffEntry.since).getTime();
  if (elapsed < 8 * 60 * 60 * 1000) {
    isInHumanMode = true;
  } else {
    delete staticData.humanHandoff[from];
  }
}
return [{ json: { ...$input.first().json, isInHumanMode } }];

const from = $input.first().json.from;
const session = $input.first().json.session;
return [{ json: { to: from, session, responseText: 'Desculpe, ainda não consigo ouvir áudios ou visualizar imagens. 😅\n\nPor favor, digite sua dúvida em texto para que eu possa te ajudar!' } }];

const from = $input.first().json.from;
const session = $input.first().json.session;
const hour = new Date().getHours();
const greetings = [
  'Bom dia! Bem-vindo à LongView 🏢

Sou o assistente virtual e estou aqui para te ajudar com informações sobre nossos empreendimentos de alto padrão.

Como posso te auxiliar?',
  'Boa tarde! Bem-vindo à LongView 🏢

Sou o assistente virtual e estou aqui para te ajudar com informações sobre nossos empreendimentos de alto padrão.

Como posso te auxiliar?',
  'Boa noite! Bem-vindo à LongView 🏢

Sou o assistente virtual e estou aqui para te ajudar com informações sobre nossos empreendimentos de alto padrão.

Como posso te auxiliar?'
];
const idx = hour < 12 ? 0 : hour < 18 ? 1 : 2;
return [{ json: { to: from, session, responseText: greetings[idx] } }];

const qdrantResp = $input.first().json;
// Se a coleção 'longview_historico' ainda não existe ou o Qdrant falhou,
// onError=continueRegularOutput devolve { error: ... } aqui -- tratamos
// isso como 'sem histórico' em vez de quebrar o atendimento.
const points = qdrantResp.error ? [] : (qdrantResp.result?.points || []);
const parsedData = $('Verificar Estado').first().json;
const currentMessage = parsedData.message;
const sorted = [...points].sort((a, b) => new Date(a.payload.timestamp) - new Date(b.payload.timestamp));
const historyLines = sorted.map(p => `Cliente: ${p.payload.pergunta_cliente || ''}\nAssistente: ${(p.payload.resposta_ia || '').slice(0, 200)}`).join('\n\n');
const hasHistory = historyLines.trim().length > 0;
return [{ json: { ...parsedData, hasHistory, historyLines, originalMessage: currentMessage } }];

