const geminiResp = $input.first().json;
const contextData = $('Preparar Contexto Histórico').first().json;
// Se a reformulação falhar (rate limit/timeout), cai para a pergunta original
// em vez de quebrar a execução -- não pode impedir o fallback de transbordo.
const falhouReformular = !!geminiResp.error;
const reformulada = !falhouReformular
  ? (geminiResp.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || contextData.originalMessage)
  : contextData.originalMessage;
return [{ json: { ...contextData, message: reformulada, messageOriginal: contextData.originalMessage } }];

const qdrantResult = $input.first().json;
// Se o Embedding OU a Busca no Qdrant falharem (429, timeout, serviço fora do ar),
// o resultado chega aqui como { error: ... } -- tratamos como 'sem contexto' com
// motivo técnico, em vez de quebrar a execução e perder o transbordo.
const apiFalhou = !!qdrantResult.error;
const results = apiFalhou ? [] : (qdrantResult.result || []);
const prevNode = $('Montar Query Enriquecida').first().json;
const MIN_SCORE = 0.72;
const validResults = results.filter(r => r.score >= MIN_SCORE);
const hasContext = validResults.length > 0;
const topScore = results.length > 0 ? results[0].score : 0;
const contextText = validResults.map(r => `Documento: ${r.payload?.metadata?.source || r.payload?.source || 'Material LongView'}\nTrecho: ${r.payload?.text || r.payload?.pageContent || ''}\n(Relevância: ${(r.score * 100).toFixed(0)}%)`).join('\n\n---\n\n');
return [{ json: { ...prevNode, hasContext, contextText, topScore, shouldHandoff: !hasContext, handoffReason: apiFalhou ? 'erro_tecnico_api' : (!hasContext ? 'sem_contexto_suficiente' : null) } }];

