const ATTENDANT_PHONE = 'SEU_NUMERO_AQUI@c.us';
const from = $('Verificar Estado').first().json.from;
const session = $('Verificar Estado').first().json.session;
const question = $('Verificar Estado').first().json.message;
const isCritical = $('Verificar Estado').first().json.isCritical || false;
// Nem sempre 'Validação de Confiança' rodou nesta execução: no caminho de
// assunto crítico o RAG inteiro é pulado, então o nó nunca executa. Referenciar
// um nó que não rodou lança erro no n8n -- por isso o try/catch abaixo.
let topScore = 0;
try {
  topScore = $('Validação de Confiança').first().json.topScore || 0;
} catch (e) {
  topScore = 0; // assunto crítico: não houve busca no RAG, não há score
}
const inputData = $input.first().json;
const apiFalhou = !!inputData.error;
const handoffReason = isCritical
  ? 'assunto_critico'
  : (apiFalhou ? 'erro_tecnico_api' : (inputData.handoffReason || 'ia_rejeitou_contexto'));
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
const alreadyInHandoff = !!staticData.humanHandoff[from];
staticData.humanHandoff[from] = { since: new Date().toISOString(), reason: handoffReason };
const reasonLabel = {
  assunto_critico: '🔴 Assunto crítico (jurídico/rescisão/procon)',
  sem_contexto_suficiente: '🟡 Fora da base de conhecimento',
  sem_contexto: '🟡 Fora da base de conhecimento',
  ia_rejeitou_contexto: '🟠 IA julgou trecho insuficiente',
  erro_tecnico_api: '🔴 Falha técnica ao gerar resposta (API fora do ar/limite atingido)'
}[handoffReason] || '🟡 Motivo não identificado';
const attendantMsg = alreadyInHandoff ? `📩 *Nova mensagem — cliente em atendimento*\n\n*Cliente:* ${from.replace('@c.us','')}\n*Mensagem:* "${question}"` : `🔔 *Novo Transbordo — LongView*\n\n*Cliente:* ${from.replace('@c.us','')}\n*Última mensagem:* "${question}"\n*Motivo:* ${reasonLabel}\n*Score RAG:* ${(topScore*100).toFixed(0)}%\n*Horário:* ${new Date().toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}\n\nPara reativar a IA após atender, envie *#bot*.`;
return [{ json: { from, session, clientMessage: alreadyInHandoff ? null : 'Compreendo perfeitamente. Estou transferindo você agora para um dos nossos especialistas LongView para garantir o melhor atendimento. Em breve entraremos em contato! 🏢', attendantMessage: attendantMsg, attendantPhone: ATTENDANT_PHONE, handoffReason, topScore, alreadyInHandoff } }];

const geminiResponse = $('IA Reescreve (SEM criar)').first().json;
const stateNode = $('Verificar Estado').first().json;
const rawText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
let responseText;
try {
  const parsed = JSON.parse(rawText);
  responseText = parsed.texto || 'Desculpe, ocorreu um erro ao processar sua mensagem. Um de nossos especialistas entrará em contato.';
} catch (e) {
  // Gemini não devolveu JSON válido -- não deveria acontecer com response_mime_type
  // 'application/json', mas se acontecer, não travamos: caímos numa mensagem segura.
  responseText = 'Desculpe, ocorreu um erro ao processar sua mensagem. Um de nossos especialistas entrará em contato.';
}
return [{ json: { to: stateNode.from, phone: stateNode.phone, session: stateNode.session, responseText: responseText.trim(), originalMessage: stateNode.message, timestamp: stateNode.timestamp || new Date().toISOString(), topScore: $('Validação de Confiança').first().json.topScore || 0, contextText: $('Validação de Confiança').first().json.contextText || '' } }];

const data = $input.first().json;
const phone = data.phone || data.to?.replace('@c.us','') || 'desconhecido';
const timestamp = data.timestamp || new Date().toISOString();
const payload = { points: [{ id: Date.now(), vector: [0], payload: { tipo: 'conversa_ia', telefone: phone, sessao: data.session || 'default', pergunta_cliente: data.originalMessage || '', resposta_ia: data.responseText || '', contexto_usado: data.contextText || '', score_relevancia: data.topScore || 0, timestamp: timestamp, data_hora_br: new Date(timestamp).toLocaleString('pt-BR', {timeZone: 'America/Sao_Paulo'}) } }] };
return [{ json: { payload, phone, timestamp } }];

const from = $('Preparar Transbordo').first().json.from;
const phone = from.replace('@c.us','');
const stateNode = $('Verificar Estado').first().json;
const transbordoData = $('Preparar Transbordo').first().json;
const timestamp = new Date().toISOString();
const payload = { points: [{ id: Date.now(), vector: [0], payload: { tipo: 'transbordo', telefone: phone, sessao: stateNode.session || 'default', pergunta_cliente: stateNode.message || '', resposta_ia: '[TRANSBORDO]', motivo_transbordo: transbordoData.handoffReason || 'desconhecido', score_relevancia: transbordoData.topScore || 0, timestamp: timestamp, data_hora_br: new Date(timestamp).toLocaleString('pt-BR', {timeZone: 'America/Sao_Paulo'}) } }] };
return [{ json: { payload } }];

const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData || {})[0] || 'file';
const fileName = binaryData?.[binaryKey]?.fileName || 'documento.pdf';
const fileNameClean = fileName.replace(/\.pdf$/i, '');
return [{ json: { source: fileNameClean, fileName, uploadedAt: new Date().toISOString() }, binary: binaryData }];

const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData || {})[0] || 'file';
const fileName = binaryData?.[binaryKey]?.fileName || 'tabela.pdf';
const fileNameClean = fileName.replace(/\.(pdf|csv|txt)$/i, '');
const tipoDoc = $input.first().json['Tipo de documento'] || 'Documento';
return [{ json: { source: fileNameClean, fileName, tipoDoc, isStructured: true, uploadedAt: new Date().toISOString() }, binary: binaryData }];

// Bot em modo silêncio — atendente humano está respondendo
// Não faz nada, apenas deixa o fluxo terminar
return [{ json: { silencio: true, from: $input.first().json.from } }];
